#!/usr/bin/env python3
# -*- coding: utf-8 -*-

#Generated by LLM, reviewed

"""
RDTSC Benchmark Visualizer & Stage Breakdown Engine
Automatically reads benchmark_results.json and creates clean, high-readability stacked charts.
Supports full-operation stacked bar breakdown, dedicated CPUID VM-Exit analysis, EPT hook breakdown, and MSR #GP architecture insight.
"""

import os
import sys
import json
import tempfile

os.environ.setdefault('MPLCONFIGDIR', os.path.join(tempfile.gettempdir(), 'matplotlib_cache'))

import numpy as np
import matplotlib.pyplot as plt
import matplotlib.ticker as ticker
from matplotlib.patches import Patch

# Configure matplotlib font and style
plt.rcParams['font.sans-serif'] = ['DejaVu Sans', 'Segoe UI', 'Arial', 'Microsoft JhengHei', 'SimHei']
plt.rcParams['axes.unicode_minus'] = False
plt.style.use('seaborn-v0_8-whitegrid' if 'seaborn-v0_8-whitegrid' in plt.style.available else 'default')

def find_json_path():
    """Locate benchmark_results.json in common project directories."""
    script_dir = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        sys.argv[1] if len(sys.argv) > 1 and not sys.argv[1].startswith("--") else None,
        "benchmark_results.json",
        os.path.join(script_dir, "benchmark_results.json"),
        os.path.join(script_dir, "..", "benchmark_results.json"),
        os.path.join(script_dir, "..", "x64", "Release", "benchmark_results.json"),
        "EIHvControlCenter/benchmark_results.json",
        "x64/Release/benchmark_results.json",
        "latest_benchmark.json",
        os.path.join(script_dir, "latest_benchmark.json")
    ]
    for p in candidates:
        if p and os.path.exists(p):
            return p
    return None

def load_data(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    runs = []
    if "runs" in data:
        runs = data["runs"]
    elif "benchmarks" in data:
        runs = [data]
    return runs

def get_operation_color(name):
    name_lower = name.lower()
    if "baseline" in name_lower:
        return "#4A90E2"  # Slate Blue
    elif "cpuid" in name_lower:
        return "#9B59B6"  # Purple (VM-Exit)
    elif "msr" in name_lower:
        return "#E67E22"  # Amber Orange
    elif "clean" in name_lower or "yield" in name_lower:
        return "#27AE60"  # Emerald Green (Clean native)
    elif "ept" in name_lower or "hook" in name_lower:
        return "#E74C3C"  # Crimson Red (EPT Hook overhead)
    return "#34495E"

def plot_single_run(run, save_path="benchmark_chart.png", all_runs=None):
    benchmarks = run.get("benchmarks", [])
    if not benchmarks:
        print("[-] No benchmark items found in run.")
        return

    run_id = run.get("run_id", 1)
    timestamp = run.get("timestamp", "N/A")
    core_id = run.get("core_id", 0)
    iterations = run.get("iterations", 10000)

    names = [b["name"] for b in benchmarks]
    min_cycles = [b["min_cycles"] for b in benchmarks]
    avg_cycles = [b["avg_cycles"] for b in benchmarks]

    fig = plt.figure(figsize=(16, 11))
    gs = fig.add_gridspec(2, 3, height_ratios=[1.3, 1.0], hspace=0.38, wspace=0.28)

    # -------------------------------------------------------------
    # Plot 1 (Top Full Width): Stacked Horizontal Bar Chart (所有操作之流程損耗多區塊堆疊長條圖)
    # -------------------------------------------------------------
    ax1 = fig.add_subplot(gs[0, :])
    y_pos = np.arange(len(names))
    # Filter valid cycles and guard against astronomical outliers
    valid_cycles = [b["min_cycles"] for b in benchmarks if 0 < b.get("min_cycles", 0) < 1000000]
    max_val = max(valid_cycles) if valid_cycles else 500
    if max_val < 500: max_val = 500

    legend_patches = {}

    for idx, (b, y) in enumerate(zip(benchmarks, y_pos)):
        stages = b.get("breakdown", [])
        total_min = b.get("min_cycles", 0)
        stage_sum = sum(st.get("cycles", 0) for st in stages) if stages else 0

        # Draw segmented bar only if stage sum is reasonable and within plot range
        if stages and 0 < stage_sum <= max(total_min * 2, max_val * 1.5):
            left_offset = 0
            for st in stages:
                w = st.get("cycles", 0)
                st_name = st.get("stage", "Stage")
                st_color = st.get("color", get_operation_color(b["name"]))

                ax1.barh(y, w, left=left_offset, height=0.62, color=st_color,
                         edgecolor="#1C2833", linewidth=1.1, alpha=0.92)

                if st_name not in legend_patches:
                    legend_patches[st_name] = Patch(facecolor=st_color, edgecolor="#1C2833", label=st_name)

                # Segment cycle count text if bar segment is wide enough
                if w > max_val * 0.08:
                    pct = (w / total_min * 100.0) if total_min > 0 else 0
                    lbl = f"{w:,}c ({pct:.0f}%)"
                    ax1.text(left_offset + w / 2, y, lbl,
                             ha='center', va='center', fontsize=8.5, fontweight='bold', color="#FFFFFF")

                left_offset += w

            # Total cycles label at end of stacked bar
            total_lbl = f" Total: {total_min:,} c"
            ax1.text(left_offset + (max_val * 0.015), y, total_lbl,
                     va='center', ha='left', fontsize=10, fontweight='bold', color="#2C3E50")
        else:
            # Clean fallback to solid bar if no stages or stage values corrupted
            draw_w = min(total_min, max_val * 1.1)
            c = get_operation_color(b["name"])
            ax1.barh(y, draw_w, height=0.62, color=c, edgecolor="#1C2833", linewidth=1.1, alpha=0.92)
            ax1.text(draw_w + (max_val * 0.015), y, f"{total_min:,} c",
                     va='center', ha='left', fontsize=10, fontweight='bold', color="#2C3E50")

    ax1.set_yticks(y_pos)
    ax1.set_yticklabels(names, fontsize=10.5, fontweight='bold')
    ax1.invert_yaxis()  # Top-down order
    ax1.set_xlabel("Cycle Latency (Segmented by Process / Stage Overhead)", fontsize=11.5, fontweight='bold', labelpad=8)
    ax1.set_title(f"RDTSC Process Latency Breakdown Dashboard (Run #{run_id} | Core #{core_id} | {iterations:,} Iterations)\n"
                  f"Timestamp: {timestamp} | Strict Instruction Serialization (_mm_lfence + _mm_mfence)",
                  fontsize=12.5, fontweight='bold', pad=12)

    ax1.set_xlim(0, max_val * 1.28)
    ax1.xaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: f"{int(x):,}"))
    ax1.grid(axis='x', linestyle='--', alpha=0.55)

    # -------------------------------------------------------------
    # Plot 2 (Bottom Left): CPUID 專屬虛擬化攔截分析 (Native vs VM-Exit)
    # -------------------------------------------------------------
    ax2 = fig.add_subplot(gs[1, 0])
    cpuid_items = [b for b in benchmarks if "cpuid" in b["name"].lower()]
    if cpuid_items:
        c_names = ["Leaf 0\n(Vendor)" if "0" in b["name"] else "Leaf 1\n(Features)" for b in cpuid_items]
        c_mins = [b["min_cycles"] for b in cpuid_items]
        width = 0.45
        x_pos = np.arange(len(cpuid_items))

        for i, (b, xp) in enumerate(zip(cpuid_items, x_pos)):
            stages = b.get("breakdown", [])
            if len(stages) > 1:
                base_c = stages[0]["cycles"]
                exit_c = stages[1]["cycles"]
                ax2.bar(xp, base_c, width, label='Bare-Metal Base' if i == 0 else "", color="#3498DB", edgecolor="#1C2833", linewidth=1.1)
                ax2.bar(xp, exit_c, width, bottom=base_c, label='Hypervisor VM-Exit' if i == 0 else "", color="#9B59B6", edgecolor="#1C2833", linewidth=1.1)
                ax2.text(xp, base_c + exit_c + 30, f"{base_c + exit_c:,} c\n(+{exit_c:,} exit)",
                         ha='center', va='bottom', fontsize=9, fontweight='bold')
            else:
                c_val = b["min_cycles"]
                ax2.bar(xp, c_val, width, color="#27AE60", edgecolor="#1C2833", linewidth=1.1)
                ax2.text(xp, c_val + 20, f"{c_val:,} c\n(Native)",
                         ha='center', va='bottom', fontsize=9, fontweight='bold')

        ax2.set_xticks(x_pos)
        ax2.set_xticklabels(c_names, fontsize=9.5, fontweight='bold')
        ax2.set_ylabel("Cycles (Lower is Faster)", fontsize=10, fontweight='bold')
        ax2.set_title("CPUID: Native vs. VM-Exit", fontsize=11, fontweight='bold')
        has_labels = any(len(b.get("breakdown", [])) > 1 for b in cpuid_items)
        if has_labels:
            ax2.legend(loc='upper left', frameon=True, fontsize=8)
        ax2.yaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: f"{int(x):,}"))
        ax2.grid(axis='y', linestyle='--', alpha=0.6)
        ax2.set_ylim(0, max(c_mins) * 1.35 if c_mins else 1500)
    else:
        ax2.text(0.5, 0.5, "No CPUID data detected", ha='center', va='center', fontsize=11)

    # -------------------------------------------------------------
    # Plot 3 (Bottom Center): Syscall & EPT Hook 流程切分
    # -------------------------------------------------------------
    ax3 = fig.add_subplot(gs[1, 1])
    syscall_items = [b for b in benchmarks if "syscall" in b["name"].lower() or "yield" in b["name"].lower() or "file" in b["name"].lower()]
    
    if syscall_items:
        def format_syscall_label(name):
            nl = name.lower()
            if "yield" in nl:
                return "NtYield\n(Native Clean)"
            elif "query" in nl or "ssdt" in nl:
                return "NtQuerySystemInfo\n(EPT SSDT Hook)"
            elif "createfile" in nl or "file" in nl:
                return "NtCreateFile\n(EPT PreHook)"
            return name
        sc_names = [format_syscall_label(b["name"]) for b in syscall_items]
        sc_mins = [b["min_cycles"] for b in syscall_items]
        sc_colors = [get_operation_color(b["name"]) for b in syscall_items]

        bars3 = ax3.bar(sc_names, sc_mins, color=sc_colors, width=0.45, edgecolor="#1C2833", linewidth=1.1)
        ax3.set_ylabel("Min Cycles", fontsize=10, fontweight='bold')
        ax3.set_title("Syscall: Native vs. EPT Hooked", fontsize=11, fontweight='bold')
        ax3.yaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: f"{int(x):,}"))
        for b, v in zip(bars3, sc_mins):
            ax3.text(b.get_x() + b.get_width()/2, b.get_height() + (max(sc_mins) * 0.02),
                     f"{v:,}", ha='center', va='bottom', fontsize=9, fontweight='bold')
        ax3.set_ylim(0, max(sc_mins) * 1.25)
        ax3.grid(axis='y', linestyle='--', alpha=0.6)
    else:
        ax3.text(0.5, 0.5, "No Syscall items detected", ha='center', va='center', fontsize=11)

    # -------------------------------------------------------------
    # Plot 4 (Bottom Right): MSR #GP Distortion vs True Ring 0 MSR Insight
    # -------------------------------------------------------------
    ax4 = fig.add_subplot(gs[1, 2])
    msr_items = [b for b in benchmarks if "msr" in b["name"].lower()]

    comp_labels = ["Ring 3 MSR\n(#GP Fault)", "Ring 0 MSR\n(Bare-Metal)", "Ring 0 MSR\n(VMM Active)"]
    comp_mins = [0, 0, 0] # 0 if no data available - strictly no arbitrary baseline numbers
    comp_is_real = [False, False, False]
    comp_colors = ["#C0392B", "#27AE60", "#9B59B6"]
    
    # Check if current run has real MSR measurements
    for b in msr_items:
        name_lower = b["name"].lower()
        cycles = b.get("min_cycles", 0)
        if "ring 0" in name_lower:
            if cycles > 500:
                comp_mins[2] = cycles
                comp_is_real[2] = True
            else:
                comp_mins[1] = cycles
                comp_is_real[1] = True
        elif "ring 3" in name_lower or "ring3" in name_lower or "seh" in b.get("diagnosis", "").lower() or "#gp" in name_lower:
            comp_mins[0] = cycles
            comp_is_real[0] = True

    # If a category was not tested in current run, check if historical runs had it
    if all_runs and len(all_runs) > 1:
        for prev_run in reversed(all_runs[:-1]):
            prev_msr = [b for b in prev_run.get("benchmarks", []) if "msr" in b.get("name", "").lower()]
            for pb in prev_msr:
                p_name = pb.get("name", "").lower()
                p_cyc = pb.get("min_cycles", 0)
                if "ring 0" in p_name:
                    if p_cyc > 500 and comp_mins[2] == 0:
                        comp_mins[2] = p_cyc
                        comp_is_real[2] = True
                    elif p_cyc <= 500 and comp_mins[1] == 0:
                        comp_mins[1] = p_cyc
                        comp_is_real[1] = True
                elif ("ring 3" in p_name or "ring3" in p_name or "#gp" in p_name) and comp_mins[0] == 0:
                    comp_mins[0] = p_cyc
                    comp_is_real[0] = True

    bars4 = ax4.bar(comp_labels, comp_mins, color=comp_colors, width=0.48, edgecolor="#1C2833", linewidth=1.1)
    ax4.set_ylabel("Cycles (Lower is Faster)", fontsize=10, fontweight='bold')
    ax4.set_title("MSR: #GP Distortion vs. Ring 0", fontsize=11, fontweight='bold')
    ax4.yaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: f"{int(x):,}"))
    ax4.grid(axis='y', linestyle='--', alpha=0.6)

    max_c = max(comp_mins)
    ylim_top = max(max_c * 1.3, 100)
    ax4.set_ylim(0, ylim_top)

    for idx, (bar, val) in enumerate(zip(bars4, comp_mins)):
        real = comp_is_real[idx]
        if real and val > 0:
            if idx == 0:
                desc = "\n(Live #GP Trap)"
            elif idx == 1:
                desc = "\n(Live Native)"
            else:
                desc = "\n(Live VM-Exit)"
            ax4.text(bar.get_x() + bar.get_width()/2, bar.get_height() + (ylim_top * 0.02),
                     f"{val:,} c{desc}", ha='center', va='bottom', fontsize=8.2, fontweight='bold', color="#1C2833")
        else:
            # Explicitly show 0 c (No Data) as requested by user
            ax4.text(bar.get_x() + bar.get_width()/2, (ylim_top * 0.02),
                     "0 c\n(No Data)", ha='center', va='bottom', fontsize=8.2, fontweight='bold', color="#7F8C8D")

    # Save high-resolution chart safely and free figure resources
    plt.savefig(save_path, dpi=180, bbox_inches='tight')
    plt.close(fig)
    print(f"[+] High-resolution chart saved successfully: {os.path.abspath(save_path)}")

def plot_multiple_runs(runs, save_path="benchmark_multi_runs_chart.png"):
    """Compare Min Cycles across multiple benchmark runs."""
    fig, ax = plt.subplots(figsize=(14, 8))
    
    # Collect all unique operation names across all runs
    op_names = []
    for r in runs:
        for b in r.get("benchmarks", []):
            if b.get("name") and b["name"] not in op_names:
                op_names.append(b["name"])
    n_ops = len(op_names)
    n_runs = len(runs)
    
    x = np.arange(n_ops)
    total_width = 0.8
    bar_width = total_width / n_runs
    
    palette = ["#3498DB", "#E74C3C", "#2ECC71", "#F39C12", "#9B59B6", "#1ABC9C"]
    
    for i, run in enumerate(runs):
        run_id = run.get("run_id", i + 1)
        timestamp = run.get("timestamp", f"Run {i+1}")
        benchmarks = run.get("benchmarks", [])
        run_mins = []
        for name in op_names:
            match = next((b["min_cycles"] for b in benchmarks if b["name"] == name), 0)
            run_mins.append(match)
        
        offset = (i - (n_runs - 1) / 2) * bar_width
        color = palette[i % len(palette)]
        bars = ax.bar(x + offset, run_mins, bar_width, label=f"Run #{run_id} ({timestamp})", color=color, alpha=0.88, edgecolor="#2C3E50")
        
        # Add labels on top of bars
        for bar, val in zip(bars, run_mins):
            if val > 0:
                ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 15,
                        f"{val:,}", ha='center', va='bottom', fontsize=8, rotation=45)

    ax.set_xticks(x)
    short_names = [n.replace("Syscall ", "").replace("Leaf ", "L") for n in op_names]
    ax.set_xticklabels(short_names, rotation=25, ha='right', fontsize=10, fontweight='medium')
    ax.set_ylabel("Minimum Cycles", fontsize=12, fontweight='bold')
    ax.set_title(f"Multi-Run Comparative Benchmark ({n_runs} Runs Recorded)\n"
                 f"Evolution of Min Cycles across different states (e.g. Bare-Metal vs. Hypervisor Active)",
                 fontsize=14, fontweight='bold', pad=15)
    ax.legend(loc='upper left', frameon=True, fontsize=10)
    ax.yaxis.set_major_formatter(ticker.FuncFormatter(lambda v, p: f"{int(v):,}"))
    ax.grid(axis='y', linestyle='--', alpha=0.6)
    
    plt.savefig(save_path, dpi=180, bbox_inches='tight')
    plt.close(fig)
    print(f"[+] Multi-run comparison chart saved successfully: {os.path.abspath(save_path)}")

def main():
    json_path = find_json_path()
    if not json_path:
        print("[-] Could not find benchmark_results.json or latest_benchmark.json.")
        print("[*] Please run EIHvControlCenter.exe option [3] first to generate benchmark data.")
        sys.exit(1)

    print(f"[+] Loading benchmark data from: {os.path.abspath(json_path)}")
    runs = load_data(json_path)
    if not runs:
        print("[-] No benchmark run records found.")
        sys.exit(1)

    print(f"[+] Found {len(runs)} benchmark run(s). Generating charts...")

    # Always plot the latest run detailed breakdown
    latest_run = runs[-1]
    plot_single_run(latest_run, "benchmark_chart.png", runs)

    # If multiple runs exist, plot the multi-run comparison chart
    if len(runs) > 1:
        plot_multiple_runs(runs, "benchmark_multi_runs_chart.png")

    # Show chart window if interactive terminal/user environment
    try:
        if "--no-show" not in sys.argv and hasattr(sys.stdout, 'isatty') and sys.stdout.isatty():
            plt.show()
    except Exception:
        pass

if __name__ == "__main__":
    main()
